for (const encoded of unsupportedCF) {
  if (supportedMissingDxfInputs.has(encoded) || supportedInactiveCF.has(encoded)) continue;
  const input = Buffer.from(encoded, 'base64');
  assertRejected(input, 'none', true, 'unsupported conditional formats must be rejected', /conditional formatting/);
}
const unsupportedLinks = await loadFixture('./links-unsupported.json');
assert.equal(unsupportedLinks.length, 3, 'unsupported hyperlink fixture count');
for (const [j, encoded] of unsupportedLinks.entries()) {
  const input = Buffer.from(encoded, 'base64');
  assertRejected(input, 'none', true, 'unsupported links must be rejected', j < 2 ? /unsupported hyperlink URL/ : /links exceed the supported tile budget/);
}
const unsupportedRuns = await loadFixture('./plain-run-unsupported.json');
assert.equal(unsupportedRuns.length, 6, 'unsupported rich-text run fixture count');
const repeatedPropsLegacy = await loadFixture('./repeated-props-legacy.json');
assert.equal(repeatedPropsLegacy.length, 1, 'previously unsupported repeated font fixture count');
assert.equal(repeatedPropsLegacy[0].input, unsupportedRuns[4]);
await verifyCase(repeatedPropsLegacy[0], 'repeated-props-legacy');
const repeatedChildrenLegacy = await loadFixture('./repeated-children-legacy.json');
assert.deepEqual(repeatedChildrenLegacy.map(c => c.input), [unsupportedRuns[2], unsupportedRuns[3]]);
for (const [j, c] of repeatedChildrenLegacy.entries()) await verifyCase(c, `repeated-children-legacy ${j}`);
const largeFontLegacy = await loadFixture('./large-font-legacy.json');
assert.equal(largeFontLegacy.length, 1, 'previously unsupported large font fixture count');
assert.equal(largeFontLegacy[0].input, unsupportedRuns[5]);
await verifyCase(largeFontLegacy[0], 'large-font-legacy');
for (const [j, encoded] of unsupportedRuns.entries()) {
  if (j >= 2) continue;
  const input = Buffer.from(encoded, 'base64');
  assertRejected(input, 'none', true, 'unsupported rich-text runs must be rejected', /rich text/);
}
const largeFill = Buffer.from(await loadFixture('./base-fill-too-large.json'), 'base64');
assertRejected(largeFill, 'none', true, 'oversized base fills must be rejected', /row or column fill exceeds the supported view size/);
const largeBorder = Buffer.from(await loadFixture('./base-border-too-large.json'), 'base64');
assertRejected(largeBorder, 'none', true, 'oversized base borders must be rejected', /row or column border exceeds the supported view size/);
const largeTintedBorder = Buffer.from(await loadFixture('./base-border-tint-too-large.json'), 'base64');
assert.equal(createHash('sha256').update(largeTintedBorder).digest('hex'), '5b75bd4857e715839a0f560d51e32b99db274072b527640bdc3e92e1c3a5c915', 'oversized tinted border input identity');
assertRejected(largeTintedBorder, 'none', true, 'oversized tinted base borders must be rejected', /^xlsx: row or column border exceeds the supported view size$/);
// cells.json[0] used to be rejected but its styles are supported now; the
// remaining unsupported style fixtures below still assert rejection.
const styled = (await loadFixture('./cells.json'))[0];
assert.ok(renderResult(Buffer.from(styled.input, 'base64'), 'none', true).bdf);
const autoHeight = await loadFixture('./auto-height.json');
assert.ok(renderResult(Buffer.from(autoHeight, 'base64'), 'none', true).bdf, 'nondefault font sizes on auto-height rows must convert');
const unsupportedBase = await loadFixture('./base-style-unsupported.json');
assert.equal(unsupportedBase.length, 4, 'row and column fill and border fixtures');
for (const encoded of unsupportedBase) {
  const input = Buffer.from(encoded, 'base64');
  assertRejected(input, 'none', true, 'unsupported base styles must be rejected', /row or column styles with (fills|complex borders)/);
}
tracker.writeIds();
process.stderr.write(`${tracker.summary()}\n`);
console.log(`${checked} XLSX rendering cases checked against upstream.`);
